export default () => {
    const languages = process.env.LANG_LIST;
    if (typeof languages === 'undefined') {
        return;
    }
    const languagesList = languages.split(',');
    // Создаем languageConfig динамически на основе languagesList
    const languageConfig = {};
    languagesList.forEach((lang) => {
        languageConfig[lang] = {
            selector: `.lang-${lang}`,
            patterns: [`/${lang}/`]
        };
    })

    // Получаем текущий URL
    const currentUrl = window.location.href;
    // Определяем активный язык (по умолчанию первый из доступных)
    let activeLang = languagesList[0];
    // Проверяем все языки из конфигурации
    for (const [lang, config] of Object.entries(languageConfig)) {
        const hasPattern = config.patterns.some(pattern => currentUrl.includes(pattern));
        if (hasPattern) {
            activeLang = lang;
            break;
        }
    }
    // Устанавливаем активный класс
    for (const [lang, config] of Object.entries(languageConfig)) {
        const element = document.querySelector(config.selector);
        if (element) {
            if (lang === activeLang) {
                element.classList.add('active');
            } else {
                element.classList.remove('active');
            }
        }
    }
}