// menuModule.js
export const MenuManager = (() => {
    let menuState = 0;
    const $ = jQuery;

    // Селекторы
    const selectors = {
        menuReveal: '#de-menu-reveal',
        menuContainer: '#de-menu-container',
        menuWrap: '.mainmenu-v2-wrap',
        menuLinks: '#mainmenu-v2 a',
        languageBlock: '.language-block',
        body: 'body',
        header: 'header',
        htmlBody: 'html,body'
    };

    // Функции для открытия/закрытия меню
    const openMenu = () => {
        $(selectors.menuReveal).addClass('menu-open');
        $(selectors.menuContainer).addClass('menu-open');
        $(selectors.htmlBody).addClass("no-scroll");

        if(!$(selectors.body).hasClass("dark-scheme")){
            $(selectors.header).addClass("header-light");
        }

        menuState = 1;
        $(selectors.languageBlock).fadeOut(300);
    };

    const closeMenu = () => {
        $(selectors.menuReveal).removeClass('menu-open');
        $(selectors.menuContainer).removeClass('menu-open');
        $(selectors.htmlBody).removeClass("no-scroll");

        if(!$(selectors.body).hasClass("dark-scheme")){
            $(selectors.header).removeClass("header-light");
        }

        menuState = 0;
        $(selectors.languageBlock).fadeIn(800);
    };

    // Обработчик клика по элементам меню
    const handleMenuClick = (e) => {
        e.stopPropagation();
        menuState === 0 ? openMenu() : closeMenu();
    };

    // Обработчик клика по ссылкам меню
    const handleMenuLinkClick = (e) => {
        e.stopPropagation();
        closeMenu();
    };

    // Обработчик клика вне области меню
    const handleDocumentClick = (e) => {
        if (menuState === 1 &&
            !$(e.target).closest(`${selectors.menuReveal}, ${selectors.menuWrap}, ${selectors.menuContainer}`).length) {
            closeMenu();
        }
    };

    // Публичные методы
    return {
        init: function() {
            // Навешиваем обработчики событий
            $(selectors.menuReveal).add(selectors.menuWrap).on("click", handleMenuClick);
            $(selectors.menuLinks).on("click", handleMenuLinkClick);
            $(document).on('click', handleDocumentClick);
        },

        // Методы для внешнего управления меню
        open: openMenu,
        close: closeMenu,

        // Метод для получения текущего состояния
        getState: () => menuState,

        // Метод для разрушения (удаления обработчиков)
        destroy: function() {
            $(selectors.menuReveal).add(selectors.menuWrap).off("click", handleMenuClick);
            $(selectors.menuLinks).off("click", handleMenuLinkClick);
            $(document).off('click', handleDocumentClick);
        }
    };
})();
